-- Historical document dates; created_at remains the immutable audit timestamp.
-- Creation-time quotas are unchanged: backdating never evades a plan limit.
CREATE OR REPLACE FUNCTION public.create_document(target_business_id uuid, document_kind text, request_id uuid, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$declare new_id uuid;result jsonb;x jsonb;k integer:=0;customer uuid;dt date;issued date;today date;fingerprint text;begin if auth.uid() is null or not private.can_write_business(target_business_id) then raise exception 'Not authorized' using errcode='42501';end if;if document_kind not in('invoice','estimate') or request_id is null then raise exception 'Invalid document request';end if;fingerprint:=encode(sha256(convert_to(payload::text,'UTF8')),'hex');perform pg_advisory_xact_lock(hashtextextended(target_business_id::text||request_id::text,0));if document_kind='invoice' then select to_jsonb(i) into result from public.invoices i where business_id=target_business_id and i.request_id=create_document.request_id;else select to_jsonb(e) into result from public.estimates e where business_id=target_business_id and e.request_id=create_document.request_id;end if;if result is not null then if result->>'request_fingerprint' is distinct from fingerprint then raise exception 'This request already saved different content. Open the saved document before starting another.' using errcode='23505';end if;return result;end if;if jsonb_typeof(payload->'items') is distinct from 'array' or jsonb_array_length(payload->'items') not between 1 and 50 then raise exception 'Add 1 to 50 line items' using errcode='23514';end if;if length(coalesce(payload->>'notes',''))>4000 or length(coalesce(payload->>'customer_message',''))>4000 then raise exception 'Notes must be at most 4000 characters';end if;customer:=(payload->>'customer_id')::uuid;today:=(now() at time zone(select timezone from public.businesses where id=target_business_id))::date;
issued:=coalesce(nullif(payload->>'issue_date','')::date,today);
if issued>today or issued<date '1900-01-01' then raise exception 'Choose an issue date from 1900 through today';end if;
if nullif(payload->>'issue_date','') is not null and (payload->>'issue_date' !~ '^\d{4}-\d{2}-\d{2}$' or issued::text<>payload->>'issue_date') then raise exception 'Choose a valid issue date';end if;
dt:=nullif(case when document_kind='invoice' then payload->>'due_date' else payload->>'expires_on' end,'')::date;
if dt is not null and dt<issued then raise exception 'Due or expiration date cannot precede the issue date';end if;if document_kind='invoice' then insert into public.invoices(business_id,customer_id,issue_date,due_date,notes,customer_message,request_id,request_fingerprint,payment_links,payment_instructions) values(target_business_id,customer,issued,dt,payload->>'notes',payload->>'customer_message',request_id,fingerprint,coalesce((select payment_links from public.business_settings where business_id=target_business_id),'[]'::jsonb),coalesce((select payment_instructions from public.business_settings where business_id=target_business_id),'')) returning id into new_id;else insert into public.estimates(business_id,customer_id,issue_date,expires_on,notes,customer_message,request_id,request_fingerprint) values(target_business_id,customer,issued,dt,payload->>'notes',payload->>'customer_message',request_id,fingerprint) returning id into new_id;end if;for x in select value from jsonb_array_elements(payload->'items') loop if document_kind='invoice' then insert into public.invoice_items(invoice_id,business_id,description,quantity,unit_price,tax_rate,sort_order) values(new_id,target_business_id,btrim(x->>'description'),(x->>'quantity')::numeric,(x->>'unit_price')::numeric,coalesce((x->>'tax_rate')::numeric,0),k);else insert into public.estimate_items(estimate_id,business_id,description,quantity,unit_price,tax_rate,sort_order) values(new_id,target_business_id,btrim(x->>'description'),(x->>'quantity')::numeric,(x->>'unit_price')::numeric,coalesce((x->>'tax_rate')::numeric,0),k);end if;k:=k+1;end loop;if document_kind='invoice' then select to_jsonb(i) into result from public.invoices i where id=new_id;else select to_jsonb(e) into result from public.estimates e where id=new_id;end if;return result;end$function$;
